{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/SuperInstance/midden/blob/room-protocol/protocol/room-state.schema.json",
  "title": "room-protocol/1 — a visitable room's settled state",
  "description": "The seam that lets an outside system (PLATO, the-tap, a walker) VISIT a room built from real fleet ledgers. A room is a settled triangle: three ledger surfaces (values, walks, canon) meeting at one integer floor, read by named instruments, strained by one live wire. Every number in a room state must trace to a fixture or be declared derived/stand-in. Enforced by protocol/validate.mjs (zero-dep subset validator).",
  "type": "object",
  "required": ["protocol", "room", "instruments", "surfaces", "strain", "visitors", "provenance"],
  "additionalProperties": false,
  "properties": {
    "protocol": { "const": "room-protocol/1" },
    "room": {
      "type": "object",
      "required": ["id", "title", "kind", "generatedAt", "builder", "fixtures"],
      "additionalProperties": false,
      "properties": {
        "id": { "type": "string", "minLength": 1 },
        "title": { "type": "string", "minLength": 1 },
        "kind": { "const": "settled-triangle" },
