        },
        "builder": {
          "type": "object",
          "required": ["script", "command"],
          "additionalProperties": false,
          "properties": {
            "script": { "const": "protocol/build-room-state.mjs" },
            "command": { "const": "node protocol/build-room-state.mjs --stamp <ISO-8601>" }
          }
        },
        "fixtures": {
          "type": "object",
          "required": ["hashAlgorithm", "files"],
          "additionalProperties": false,
          "properties": {
            "hashAlgorithm": { "const": "sha256" },
            "files": {
              "type": "array",
